def close(actual, expected, tolerance=1e-9):
    # Floats are only approximately right, so compare the size of the difference (relative to the answer once that is bigger than 1).
    from numbers import Real
    if isinstance(actual, bool) or not isinstance(actual, Real):
        raise AssertionError(f"expected a number, got {actual!r}")
    if not abs(actual - expected) <= tolerance * max(1.0, abs(expected)):
        raise AssertionError(f"expected about {expected!r}, got {actual!r} (off by {abs(actual - expected):.3g})")
    return True

