def fast_power(x, n):
    if n < 0:
        x, n = 1 / x, -n               # x ** -n is (1 / x) ** n
    result = 1
    while n:
        if n & 1:                      # this bit of the exponent is 1: multiply in the matching power of x
            result *= x
        x *= x                         # x, x**2, x**4, x**8, ...
        n >>= 1
    return result
